CREATE OR REPLACE FUNCTION public.search_pseudonyms(_query text) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('pseudonym',s.pseudonym)),'[]'::jsonb) FROM (SELECT pseudonym FROM (SELECT pseudonym FROM public.posts UNION SELECT pseudonym FROM public.comments) visible WHERE char_length(trim(coalesce(_query,''))) BETWEEN 2 AND 80 AND strpos(lower(pseudonym),lower(trim(_query)))>0 ORDER BY pseudonym LIMIT 30) s $$;
REVOKE ALL ON FUNCTION public.search_pseudonyms(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.search_pseudonyms(text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.public_pseudonym_profile(_pseudonym text) RETURNS jsonb LANGUAGE sql STABLE SECURITY INVOKER SET search_path=public AS $$ SELECT jsonb_build_object('pseudonym',_pseudonym,'posts',(SELECT coalesce(jsonb_agg(to_jsonb(s)),'[]'::jsonb) FROM (SELECT id,title,body,community,pseudonym,post_type,progress,created_at,expires_at FROM public.posts WHERE pseudonym=_pseudonym ORDER BY created_at DESC LIMIT 50) s),'comments',(SELECT coalesce(jsonb_agg(to_jsonb(c)),'[]'::jsonb) FROM (SELECT c.id,c.post_id,c.body,c.created_at FROM public.comments c JOIN public.posts p ON p.id=c.post_id WHERE c.pseudonym=_pseudonym ORDER BY c.created_at DESC LIMIT 50) c)) WHERE char_length(_pseudonym) BETWEEN 1 AND 80 $$;
REVOKE ALL ON FUNCTION public.public_pseudonym_profile(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_pseudonym_profile(text) TO anon,authenticated;
REVOKE INSERT ON public.profiles FROM authenticated;
GRANT INSERT(id,email,pseudonym) ON public.profiles TO authenticated;
CREATE OR REPLACE FUNCTION public.read_conversation(_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF auth.uid() IS NULL OR public.is_banned(auth.uid()) OR NOT public.is_chat_member(_id,auth.uid()) THEN RAISE EXCEPTION 'Conversation unavailable'; END IF; INSERT INTO public.conversation_reads(conversation_id,user_id,last_read_at) VALUES(_id,auth.uid(),now()) ON CONFLICT(conversation_id,user_id) DO UPDATE SET last_read_at=excluded.last_read_at; SELECT coalesce(jsonb_agg(jsonb_build_object('id',m.id,'body',CASE WHEN m.admin_removed THEN '[Removed by admin]' ELSE m.body END,'mine',m.sender_id=auth.uid(),'is_request',m.is_request,'created_at',m.created_at) ORDER BY m.created_at),'[]'::jsonb) INTO result FROM public.messages m WHERE m.conversation_id=_id; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.list_my_conversations() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'status',c.status,'mine',c.sender_id=auth.uid(),'pseudonym',coalesce(p.pseudonym,'Someone'),'created_at',c.created_at,'unread',(SELECT count(*) FROM public.messages m WHERE m.conversation_id=c.id AND NOT m.admin_removed AND m.sender_id<>auth.uid() AND m.created_at>coalesce((SELECT last_read_at FROM public.conversation_reads WHERE conversation_id=c.id AND user_id=auth.uid()),'epoch'::timestamptz)),'last_message',(SELECT CASE WHEN m.admin_removed THEN '[Removed]' ELSE m.body END FROM public.messages m WHERE m.conversation_id=c.id ORDER BY m.created_at DESC LIMIT 1)) ORDER BY c.updated_at DESC),'[]'::jsonb) FROM public.conversations c LEFT JOIN public.profiles p ON p.id=CASE WHEN c.sender_id=auth.uid() THEN c.recipient_id ELSE c.sender_id END WHERE auth.uid() IS NOT NULL AND NOT public.is_banned(auth.uid()) AND (c.sender_id=auth.uid() OR c.recipient_id=auth.uid()) $$;
CREATE OR REPLACE FUNCTION public.request_message(_target_type text,_target_id uuid,_body text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE me uuid:=auth.uid(); other_id uuid; cid uuid; BEGIN IF me IS NULL OR public.is_banned(me) OR _target_type IS NULL OR _target_type NOT IN ('post','comment') OR _target_id IS NULL OR _body IS NULL OR char_length(trim(_body)) NOT BETWEEN 1 AND 500 THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF _target_type='post' THEN SELECT author_id INTO other_id FROM public.posts WHERE id=_target_id AND NOT(is_deleted OR author_deleted OR admin_removed) AND (expires_at IS NULL OR expires_at>now()); ELSE SELECT c.author_id INTO other_id FROM public.comments c JOIN public.posts p ON p.id=c.post_id WHERE c.id=_target_id AND NOT(c.is_deleted OR c.admin_removed OR p.is_deleted OR p.author_deleted OR p.admin_removed) AND (p.expires_at IS NULL OR p.expires_at>now()); END IF; IF other_id IS NULL OR other_id=me OR public.is_banned(other_id) THEN RAISE EXCEPTION 'Request unavailable'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('sender:'||me::text,0)); PERFORM pg_advisory_xact_lock(hashtextextended('pair:'||least(me::text,other_id::text)||':'||greatest(me::text,other_id::text),0)); IF EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=me AND blocked_id=other_id) OR (blocker_id=other_id AND blocked_id=me)) OR EXISTS(SELECT 1 FROM public.conversations WHERE (sender_id=me AND recipient_id=other_id) OR (sender_id=other_id AND recipient_id=me)) THEN RAISE EXCEPTION 'Request unavailable'; END IF; IF (SELECT count(*) FROM public.conversations WHERE sender_id=me AND created_at>=now()-interval '1 day')>=5 THEN RAISE EXCEPTION 'Daily request limit reached'; END IF; INSERT INTO public.conversations(sender_id,recipient_id) VALUES(me,other_id) RETURNING id INTO cid; INSERT INTO public.messages(conversation_id,sender_id,body,is_request) VALUES(cid,me,trim(_body),true); RETURN cid; END $$;